Warehouse warehouse = mock(Warehouse.class);
when(warehouse.hasInventory("Talisker", 50)).thenReturn(true);

Order order = new Order("Talisker", 50);
assertTrue(order.fill(warehouse));

verify(warehouse).remove("Talisker", 50);
InOrder inOrder = inOrder(warehouse);
inOrder.verify(warehouse).hasInventory("Talisker", 50);
inOrder.verify(warehouse).remove("Talisker", 50);

